use java::{JAVA_FRAMES, JAVA_TICKS};

#[test]
fn the_cape_chase_and_layer_cape_angles_match_the_java_trace() {
    assert_eq!(JAVA_TICKS.len() * 4, JAVA_FRAMES.len());
    let mut state = AppearanceState::new();
    let uuid = uuid::Uuid::from_u128(2);
    // Java's history starts at the origin (a fresh entity's `chasingPos`), which is what makes
    // tick 0 snap and overshoot. mc-rs normally seeds the history at the player; seed it at the
    // origin here so both sides start from the same state.
    state.tick_cape_chase(uuid, 0, DVec3::ZERO);
    let mut big_angles = 0;
    for (tick, row) in JAVA_TICKS.iter().enumerate() {
        let prev_pos = DVec3::new(row[0], row[1], row[2]);
        let pos = DVec3::new(row[3], row[4], row[5]);
        state.tick_cape_chase(uuid, tick as u64 + 1, pos);
        // At a zero render position the sampled offset is the chase itself: partial 0 gives
        // `prevChasingPos`, partial 1 gives `chasingPos` (the lerp is exact for these values).
        let at = |state: &mut AppearanceState, pt: f32| {
            let s = state.cape_state(uuid, 0, pos, DVec3::ZERO, pt, 0.0, 0.0, 0.0, false);
            [s.chase_dx, s.chase_dy, s.chase_dz]
        };
        assert_eq!(
            at(&mut state, 0.0),
            [row[6], row[7], row[8]],
            "tick {tick}: prevChasingPos"
        );
        assert_eq!(
            at(&mut state, 1.0),
            [row[9], row[10], row[11]],
            "tick {tick}: chasingPos"
        );
        for frame in 0..4 {
            let pt = frame as f32 / 4.0;
            let lerp = |a: f64, b: f64| a as f32 + (b as f32 - a as f32) * pt;
            let render = prev_pos + (pos - prev_pos) * f64::from(pt);
            let sampled = state.cape_state(
                uuid,
                0,
                pos,
                render,
                pt,
                lerp(row[12], row[13]),
                lerp(row[14], row[15]),
                lerp(row[16], row[17]),
                false,
            );
            let (x, z, y) = cape_angles(&sampled);
            let want = JAVA_FRAMES[tick * 4 + frame];
            assert_eq!(
                [x.to_bits(), z.to_bits(), y.to_bits()],
                [want[0].to_bits(), want[1].to_bits(), want[2].to_bits()],
                "tick {tick} frame {frame}: rust {:?} java {want:?}",
                [x, z, y]
            );
            if x.abs() > 90.0 || z.abs() > 90.0 {
                big_angles += 1;
            }
        }
    }
    // The timeline must reach the extreme branches (the spawn snap, the teleport ease).
    assert!(big_angles > 8, "only {big_angles} extreme frames");
}
